object PestsIpmBookChapter {
    val chapter = bchapter(
        lessonId = "u6-pests-ipm",
        title = "Insect pests and the principles of integrated pest management" to "பூச்சிப் பீடைகளும் ஒருங்கிணைந்த பூச்சி மேலாண்மையின் கொள்கைகளும்",
        objectives = listOf(
